    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, define f(n) = floor(n^(1/{root_order}) + (1 - {theta_shift})). Consider the sum S = sum over k = 1 to {alpha} of 1 / ({a_coeff} * f(k) + {b_const}). Find the integer floor of S.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# Choose root order r >= 3 (avoid trivial square root or linear), occasionally include 4 but with non-0.5 shift
candidates_r = [3,4,5,6,7,8]
root_order = rng.choice(candidates_r)
# Choose a rational theta in (0,1), not equal to 0.5
# Denominator between 3 and 9 to get decent fractional precision
for _ in range(100):
    d = rng.randint(3, 9)
    n = rng.randint(1, d - 1)
    theta_shift = n / d
    if abs(theta_shift - 0.5) > 1e-12 and 0.0 < theta_shift < 1.0:
        break
else:
    # Fallback if loop fails (unlikely)
    theta_shift = 0.4
# Choose coefficients for the denominator
a_coeff = rng.randint(1, 3)
b_const = rng.randint(1, 5)
# Choose alpha so that the number of distinct f(k) values is at least 6 (to enforce non-triviality)
# Start with a reasonably large range and adjust if needed
for _ in range(100):
    alpha = rng.randint(8000, 120000)
    # Estimate max m: floor(alpha^(1/r) + (1 - theta))
    m_max_est = int(math.floor(alpha ** (1.0 / root_order) + (1.0 - theta_shift)))
    if m_max_est >= 6:
        break
else:
    # Force alpha large enough
    base_needed = (6 - (1.0 - theta_shift))
    if base_needed < 1:
        base_needed = 1.0
    alpha = int(math.ceil(base_needed ** root_order)) + rng.randint(5000, 15000)
# Ensure we don't exactly replicate the seed setting (p=4, theta=0.5, special form), already ensured theta != 0.5
return {
    'alpha': alpha,
    'root_order': root_order,
    'theta_shift': theta_shift,
    'a_coeff': a_coeff,
    'b_const': b_const
}

    def verifier(assign):
import math
# Validate presence of keys
required = ['alpha', 'root_order', 'theta_shift', 'a_coeff', 'b_const']
for k in required:
    if k not in assign:
        # Missing required key
        return (False, None)
alpha = assign['alpha']
root_order = assign['root_order']
theta_shift = assign['theta_shift']
a_coeff = assign['a_coeff']
b_const = assign['b_const']
# Domain checks
if not (isinstance(alpha, int) and alpha >= 4000):  # enforce non-trivial size
    return (False, None)
if not (isinstance(root_order, int) and root_order >= 3 and root_order <= 12):
    return (False, None)
if not (isinstance(theta_shift, (int, float)) and 0.0 < float(theta_shift) < 1.0 and abs(float(theta_shift) - 0.5) > 1e-12):
    return (False, None)
if not (isinstance(a_coeff, int) and a_coeff >= 1 and a_coeff <= 10):
    return (False, None)
if not (isinstance(b_const, int) and b_const >= 1 and b_const <= 20):
    return (False, None)
# Additional difficulty enforcement: ensure enough distinct f(k) values
m_max_est = int(math.floor(alpha ** (1.0 / root_order) + (1.0 - theta_shift)))
if m_max_est < 6:
    # Too few distinct buckets; makes the sum too small/trivial to analyze
    return (False, None)
# Compute S by definition: f(k) = floor(k^(1/root_order) + (1 - theta_shift))
S = 0.0
# Vectorized/interval approach is more efficient, but we deliberately compute directly to avoid boundary errors
for k in range(1, alpha + 1):
    # Compute root carefully
    root = k ** (1.0 / root_order)
    m = int(math.floor(root + (1.0 - theta_shift)))
    S += 1.0 / (a_coeff * m + b_const)
# We return floor(S) as the integer answer
answer = int(math.floor(S + 1e-12))
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

